def parse_manuscript(md_path):
    """Parse manuscript.md and extract chapters.

    Returns dict with:
      - title: book title from first line
      - chapters: list of dicts {number, title, content_html}

    Handles both formats:
      - Book 1 & 2: `## Chapter NN` (bare) then `## Chapter N — Title` (with title)
      - Book 3: single `## Chapter N — Title` (with title)
    """
    with open(md_path, 'r', encoding='utf-8') as f:
        text = f.read()

    lines = text.split('\n')

    # Extract title from first non-empty line
    title = "Untitled"
    for line in lines:
        line = line.strip()
        if line and not line.startswith('---'):
            if line.startswith('# ') and not line.startswith('## '):
                title = line.lstrip('# ').strip()
                break
            elif line.startswith('#'):
                continue
            elif line.startswith('*'):
                continue
            else:
                title = line
                break

    # Find all chapter headings
    chapter_headings = []
    for i, line in enumerate(lines):
        stripped = line.strip()
        # Match ## Chapter N or ## Chapter N — Title
        m = re.match(r'^## Chapter (\d+)\s*(?:[—–-]\s*(.*))?$', stripped)
        if m:
            num = int(m.group(1))
            title_text = m.group(2)
            chapter_headings.append((num, title_text, i))

    # Group: find numbered-only headings (bare) and titled headings
    # For books 1 & 2, we get pairs like (01, None) then (1, "The Artemis Accord")
    # For book 3, we get (1, "The Morning Report")

    # De-duplicate: if two consecutive headings have same chapter number (or offset by one digit),
    # take the one with the title
    titled_chapters = []
    seen_nums = set()

    for num, title_text, line_num in chapter_headings:
        if title_text and title_text.strip():
            # This one has a real title
            if num not in seen_nums:
                titled_chapters.append((num, title_text.strip(), line_num))
                seen_nums.add(num)

    if not titled_chapters:
        # Fallback: use all headings
        for num, title_text, line_num in chapter_headings:
            titled_chapters.append((num, title_text.strip() if title_text else f"Chapter {num}", line_num))

    # Now extract content for each chapter
    chapters = []
    lines_with_nl = text.split('\n')

    for idx, (num, chap_title, start_line) in enumerate(titled_chapters):
        # Determine end line (start of next chapter)
        if idx + 1 < len(titled_chapters):
            end_line = titled_chapters[idx + 1][2]
        else:
            end_line = len(lines_with_nl)

        # Extract chapter content (exclude the heading line itself)
        content_lines = lines_with_nl[start_line + 1:end_line]
        content_text = '\n'.join(content_lines).strip()

        # Convert to HTML using markdown
        content_html = markdown(content_text, extensions=['extra'])

        chapters.append({
            'number': num,
            'title': chap_title,
            'content_html': content_html
        })

    return {
        'title': title,
        'chapters': chapters
    }


def build_print_html(book_info, chapters, page_map=None):
    """Build complete print-ready HTML document.

    If page_map is provided, it's a dict {chapter_num: page_number}
    Used to hardcode page numbers in the TOC.
    """
    title = book_info['title']
    subtitle = book_info['subtitle']
    series = book_info['series']
    author = book_info['author']

    # Build TOC rows
    toc_rows = []
    for ch in chapters:
        num = ch['number']
        chap_title = ch['title']
        page_str = str(page_map.get(num, '')) if page_map else ''

        # Dots leader
        if page_str:
            dots = '.' * max(3, min(50, 60 - len(chap_title)))
        else:
            dots = ''

        toc_rows.append(f'''    <tr>
      <td class="num">{num}.</td>
      <td class="title">{chap_title}</td>
      <td class="dots">{dots}</td>
      <td class="page">{page_str}</td>
    </tr>''')

    toc_html = '\n'.join(toc_rows)

    # Build chapter content
    chapters_html = []
    for ch in chapters:
        chapters_html.append(
            f'<h1 class="chapter-title" id="ch{ch["number"]}">'
            f'Chapter {ch["number"]} — {ch["title"]}</h1>\n'
            f'{ch["content_html"]}'
        )

    all_chapters = '\n\n'.join(chapters_html)

    # Build series listing
