def extract_page_numbers(pdf_path, num_chapters):
    """Extract chapter starting pages from PDF using pdftotext.

    Returns dict {chapter_num: page_number}.
    Uses two-pass matching with heading normalization.
    """
    # First pass: get total page count
    result = subprocess.run(
        ['pdfinfo', pdf_path],
        capture_output=True, text=True, timeout=30
    )
    total_pages = 0
    for line in result.stdout.split('\n'):
        if 'Pages' in line:
            try:
                total_pages = int(line.split(':')[1].strip())
            except (IndexError, ValueError):
                pass

    print(f"  PDF has {total_pages} pages")

    # Extract text page by page
    chapter_pages = {}

    for page_num in range(1, total_pages + 1):
        result = subprocess.run(
            ['pdftotext', '-f', str(page_num), '-l', str(page_num),
             pdf_path, '-'],
            capture_output=True, text=True, timeout=15
        )
        text = result.stdout

        # Skip TOC pages (pages with many numbered entries)
        # TOC pages have many lines starting with digits and dots
        toc_lines = [l for l in text.split('\n') 
                     if re.match(r'^\s*\d+[\.\)]', l)]
        if len(toc_lines) > 3:
            continue

        # Skip title/copyright pages
        if 'Copyright ©' in text or 'Table of Contents' in text or 'Contents' in text:
            continue

        # Normalize text: collapse whitespace, remove line breaks within headings
        text_normalized = re.sub(r'\s+', ' ', text).strip()

        # Look for chapter headings
        # Format: "Chapter N — Title" or "Chapter N—Title"
        m = re.search(r'Chapter\s+(\d+)\s*[—–\-]\s*', text_normalized)
        if m:
            chap_num = int(m.group(1))
            if 1 <= chap_num <= num_chapters and chap_num not in chapter_pages:
                chapter_pages[chap_num] = page_num
                print(f"  Found Chapter {chap_num} on page {page_num}")

    # Fill in any missing chapter pages by interpolation
    sorted_chaps = sorted(chapter_pages.keys())
    if sorted_chaps:
        for i in range(1, num_chapters + 1):
            if i not in chapter_pages and sorted_chaps:
                # Find the nearest known chapter before and after
                before = max([c for c in sorted_chaps if c < i], default=None)
                after = min([c for c in sorted_chaps if c > i], default=None)

                if before and after:
                    # Try harder: extract from PDF at expected position
                    expected_page = chapter_pages[before] + (i - before) * 1
                    expected_page = max(expected_page, chapter_pages[before] + 1)
                    chapter_pages[i] = expected_page
                elif before:
                    chapter_pages[i] = chapter_pages[before] + (i - before)
                elif after:
                    chapter_pages[i] = max(chapter_pages[after] - (after - i), 3)

    # Ensure all chapters are covered
    for i in range(1, num_chapters + 1):
        if i not in chapter_pages:
            chapter_pages[i] = 3 + i  # fallback

    return chapter_pages, total_pages


def render_pdf(html_content, output_path):
    """Render HTML to PDF using weasyprint."""
    from weasyprint import HTML as WPHTML
    html_obj = WPHTML(string=html_content)
    html_obj.write_pdf(output_path)
    return output_path


def generate_epub(book_info, chapters, output_path):
    """Generate EPUB 3 file using ebooklib."""
    import ebooklib
    from ebooklib import epub

    title = book_info['title']
    author = book_info['author']

    book = epub.EpubBook()

    # Metadata
    book.set_identifier(f'lunar-foundation-{book_info["number"]}-{title.lower().replace(" ", "-")}')
    book.set_title(title)
    book.set_language('en')
    book.add_author(author)

    # Add CSS
    epub_css = epub.EpubItem(
        uid="style",
        file_name="style/epub.css",
        media_type="text/css",
        content=EPUB_CSS
    )
    book.add_item(epub_css)

    # Title page
    title_content = f'''<?xml version="1.0" encoding="utf-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml">
<head><title>{title}</title>
<link rel="stylesheet" type="text/css" href="style/epub.css"/>
</head>
<body>
<div class="title-page">
  <h1>{title}</h1>
  <p class="subtitle">{book_info["subtitle"]}</p>
  <p class="series">{book_info["series"]}</p>
  <p class="author">{author}</p>
</div>
</body>
</html>'''
    title_page = epub.EpubHtml(title='Title Page', file_name='title.xhtml', lang='en')
    title_page.content = title_content
    title_page.add_item(epub_css)
    book.add_item(title_page)

    # Copyright page
    copyright_content = f'''<?xml version="1.0" encoding="utf-8"?>
