  <p>First Edition: 2026</p>
  <p>{book_info["series"]}</p>
</div>
</body>
</html>'''
    copyright_page = epub.EpubHtml(title='Copyright', file_name='copyright.xhtml', lang='en')
    copyright_page.content = copyright_content
    copyright_page.add_item(epub_css)
    book.add_item(copyright_page)

    # TOC page
    toc_rows_html = ''
    for ch in chapters:
        num = ch['number']
        chap_title = ch['title']
        toc_rows_html += f'''    <tr>
      <td class="num">{num}.</td>
      <td class="title"><a href="ch{num}.xhtml">{chap_title}</a></td>
      <td class="page"></td>
    </tr>\n'''

    toc_content = f'''<?xml version="1.0" encoding="utf-8"?>
<!DOCTYPE html>
