def parse_manuscript(md_path):
    """Parse manuscript.md and extract chapters."""
    with open(md_path, 'r', encoding='utf-8') as f:
        text = f.read()

    lines = text.split('\n')

    # Extract title from first non-empty line
    title = "Untitled"
    for line in lines:
        line = line.strip()
        if line and not line.startswith('---'):
            if line.startswith('# ') and not line.startswith('## '):
                title = line.lstrip('# ').strip()
                break
            elif line.startswith('#'):
                continue
            elif line.startswith('*'):
                continue
            else:
                title = line
                break

    # Find all chapter headings
    chapter_headings = []
    for i, line in enumerate(lines):
        stripped = line.strip()
        m = re.match(r'^## Chapter (\d+)\s*(?:[—–-]\s*(.*))?$', stripped)
        if m:
            num = int(m.group(1))
            title_text = m.group(2)
            chapter_headings.append((num, title_text, i))

    # Keep only headings with titles, deduplicated by chapter number
    titled_chapters = []
    seen_nums = set()

    for num, title_text, line_num in chapter_headings:
        if title_text and title_text.strip():
            if num not in seen_nums:
                titled_chapters.append((num, title_text.strip(), line_num))
                seen_nums.add(num)

    if not titled_chapters:
        for num, title_text, line_num in chapter_headings:
            titled_chapters.append((num, title_text.strip() if title_text else f"Chapter {num}", line_num))

    # Extract content for each chapter
    chapters = []
    for idx, (num, chap_title, start_line) in enumerate(titled_chapters):
        if idx + 1 < len(titled_chapters):
            end_line = titled_chapters[idx + 1][2]
        else:
            end_line = len(lines)

        content_lines = lines[start_line + 1:end_line]
        content_text = '\n'.join(content_lines).strip()
        content_html = markdown(content_text, extensions=['extra'])

        chapters.append({
            'number': num,
            'title': chap_title,
            'content_html': content_html
        })

    return {'title': title, 'chapters': chapters}


