def extract_page_numbers(pdf_path, num_chapters):
    """Extract chapter starting pages from PDF using pdftotext."""
    result = subprocess.run(
        ['pdfinfo', pdf_path],
        capture_output=True, text=True, timeout=30
    )
    total_pages = 0
    for line in result.stdout.split('\n'):
        if 'Pages' in line:
            try:
                total_pages = int(line.split(':')[1].strip())
            except (IndexError, ValueError):
                pass

    print(f"  PDF has {total_pages} pages")

    chapter_pages = {}

    for page_num in range(1, total_pages + 1):
        result = subprocess.run(
            ['pdftotext', '-f', str(page_num), '-l', str(page_num),
             pdf_path, '-'],
            capture_output=True, text=True, timeout=15
        )
        text = result.stdout

        toc_lines = [l for l in text.split('\n') 
                     if re.match(r'^\s*\d+[\.\)]', l)]
        if len(toc_lines) > 3:
            continue

        if 'Copyright ©' in text or 'Table of Contents' in text or 'Contents' in text:
            continue

        text_normalized = re.sub(r'\s+', ' ', text).strip()

        m = re.search(r'Chapter\s+(\d+)\s*[—–\-]\s*', text_normalized)
        if m:
            chap_num = int(m.group(1))
            if 1 <= chap_num <= num_chapters and chap_num not in chapter_pages:
                chapter_pages[chap_num] = page_num
                print(f"  Found Chapter {chap_num} on page {page_num}")

    for i in range(1, num_chapters + 1):
        if i not in chapter_pages:
            chapter_pages[i] = 3 + i

    return chapter_pages, total_pages


def render_pdf(html_content, output_path):
    """Render HTML to PDF using weasyprint."""
    from weasyprint import HTML as WPHTML
    html_obj = WPHTML(string=html_content)
    html_obj.write_pdf(output_path)
    return output_path


def generate_epub_manual(book_info, chapters, output_path):
    """Generate EPUB 3 using manual ZIP creation (avoids ebooklib bugs)."""
    title = book_info['title']
    author = book_info['author']
    book_id = f'lunar-foundation-{book_info["number"]}'

    # Build all XHTML content
    xhtml_files = {}

    # 1. Title page
    xhtml_files['title.xhtml'] = f'''<?xml version="1.0" encoding="utf-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">
<head><title>{title}</title>
<link rel="stylesheet" type="text/css" href="style/epub.css"/>
</head>
<body>
<div class="title-page">
  <h1>{title}</h1>
  <p class="subtitle">{book_info["subtitle"]}</p>
  <p class="series">{book_info["series"]}</p>
  <p class="author">{author}</p>
</div>
</body>
</html>'''

    # 2. Copyright page
    xhtml_files['copyright.xhtml'] = f'''<?xml version="1.0" encoding="utf-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">
<head><title>Copyright</title>
<link rel="stylesheet" type="text/css" href="style/epub.css"/>
</head>
<body>
<div class="copyright-page">
  <p><strong>Copyright © 2026 by {author}</strong></p>
  <p>All rights reserved.</p>
  <p>&nbsp;</p>
  <p>This is a work of fiction. Names, characters, places, and incidents either are the product of the author's imagination or are used fictitiously. Any resemblance to actual persons, living or dead, events, or locales is entirely coincidental.</p>
  <p>&nbsp;</p>
  <p>First Edition: 2026</p>
  <p>{book_info["series"]}</p>
</div>
</body>
</html>'''

    # 3. TOC page
    toc_rows = ''
    for ch in chapters:
        num = ch['number']
        chap_title = ch['title']
        toc_rows += f'''    <tr>
      <td class="num">{num}.</td>
      <td class="title"><a href="ch{num}.xhtml">{chap_title}</a></td>
      <td class="page"></td>
    </tr>\n'''

    xhtml_files['toc.xhtml'] = f'''<?xml version="1.0" encoding="utf-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">
<head><title>Contents</title>
<link rel="stylesheet" type="text/css" href="style/epub.css"/>
</head>
<body>
<div class="toc-page">
  <h1>Contents</h1>
  <table class="toc-table">
{toc_rows}
  </table>
</div>
</body>
</html>'''

    # 4. Chapter files
    for ch in chapters:
        num = ch['number']
        cap_title = f'Chapter {num} — {ch["title"]}'
        content = ch['content_html']
        content = content.replace('<p>', '<p class="first-para">', 1)

        xhtml_files[f'ch{num}.xhtml'] = f'''<?xml version="1.0" encoding="utf-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">
<head><title>{cap_title}</title>
<link rel="stylesheet" type="text/css" href="style/epub.css"/>
</head>
<body>
<h1 class="chapter-title">{cap_title}</h1>
{content}
</body>
</html>'''

    # 5. About the Author
    xhtml_files['about.xhtml'] = f'''<?xml version="1.0" encoding="utf-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">
<head><title>About the Author</title>
<link rel="stylesheet" type="text/css" href="style/epub.css"/>
</head>
<body>
<div class="back-matter">
  <h1>About the Author</h1>
  <p>{author} is a writer of speculative fiction, exploring the intersection of human resilience and technological progress. With a background in engineering and a passion for space exploration, {author} brings scientific accuracy and emotional depth to stories about humanity's future beyond Earth. The Lunar Foundation series represents a years-long project to imagine, in granular detail, what the first permanent human settlement on the Moon might actually look like — not just the hardware, but the people, the politics, and the profound changes that come from living on another world.</p>
</div>
</body>
</html>'''

    # 6. Series listing
    xhtml_files['series.xhtml'] = f'''<?xml version="1.0" encoding="utf-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">
<head><title>The Lunar Foundation</title>
<link rel="stylesheet" type="text/css" href="style/epub.css"/>
</head>
<body>
<div class="back-matter">
  <h1>The Lunar Foundation</h1>
  <ol class="series-list">
    <li><strong>Moon Rock</strong> — Book 1: The founding of the first permanent lunar base</li>
    <li><strong>Mooncoming</strong> — Book 2: The settlement takes root and faces its first existential crisis</li>
    <li><strong>Waters End</strong> — Book 3: Water — the key to survival on the Moon</li>
  </ol>
</div>
</body>
</html>'''

    # Build spine order
    spine_ids = ['title.xhtml', 'copyright.xhtml', 'toc.xhtml']
    for ch in chapters:
        spine_ids.append(f'ch{ch["number"]}.xhtml')
    spine_ids.append('about.xhtml')
    spine_ids.append('series.xhtml')

    # Build NCX (OPF 2 navigation)
    ncx_items = []
    ncx_points = []
    play_order = 1

    ncx_items.append(f'''    <navPoint id="nav-title" playOrder="{play_order}">
      <navLabel><text>Title Page</text></navLabel>
      <content src="title.xhtml"/>
    </navPoint>''')
    play_order += 1
    ncx_items.append(f'''    <navPoint id="nav-copyright" playOrder="{play_order}">
      <navLabel><text>Copyright</text></navLabel>
      <content src="copyright.xhtml"/>
    </navPoint>''')
    play_order += 1
    ncx_items.append(f'''    <navPoint id="nav-toc" playOrder="{play_order}">
      <navLabel><text>Contents</text></navLabel>
      <content src="toc.xhtml"/>
    </navPoint>''')
    play_order += 1

    for ch in chapters:
        ncx_items.append(f'''    <navPoint id="nav-ch{ch['number']}" playOrder="{play_order}">
      <navLabel><text>Chapter {ch['number']} — {ch['title']}</text></navLabel>
      <content src="ch{ch['number']}.xhtml"/>
    </navPoint>''')
        play_order += 1

    ncx_items.append(f'''    <navPoint id="nav-about" playOrder="{play_order}">
      <navLabel><text>About the Author</text></navLabel>
      <content src="about.xhtml"/>
    </navPoint>''')
    play_order += 1
    ncx_items.append(f'''    <navPoint id="nav-series" playOrder="{play_order}">
      <navLabel><text>Series Listing</text></navLabel>
      <content src="series.xhtml"/>
    </navPoint>''')

    ncx_content = f'''<?xml version="1.0" encoding="utf-8"?>
<!DOCTYPE ncx PUBLIC "-//NISO//DTD ncx 2005-1//EN"
 "http://www.daisy.org/z3986/2005/ncx-2005-1.dtd">
<ncx xmlns="http://www.daisy.org/z3986/2005/ncx/" version="2005-1">
  <head>
    <meta name="dtb:uid" content="{book_id}"/>
    <meta name="dtb:depth" content="1"/>
    <meta name="dtb:totalPageCount" content="0"/>
    <meta name="dtb:maxPageNumber" content="0"/>
  </head>
  <docTitle><text>{title}</text></docTitle>
  <docAuthor><text>{author}</text></docAuthor>
  <navMap>
{chr(10).join(ncx_items)}
  </navMap>
</ncx>'''

    # Build OPF
    manifest_items = []
    manifest_items.append(f'    <item id="css" href="style/epub.css" media-type="text/css"/>')
    manifest_items.append(f'    <item id="ncx" href="toc.ncx" media-type="application/x-dtbncx+xml"/>')

    for fn in spine_ids:
        fid = fn.replace('.xhtml', '')
        manifest_items.append(f'    <item id="{fid}" href="{fn}" media-type="application/xhtml+xml"/>')

    spine_refs = []
    for fn in spine_ids:
        fid = fn.replace('.xhtml', '')
        spine_refs.append(f'    <itemref idref="{fid}"/>')

    opf_content = f'''<?xml version="1.0" encoding="utf-8"?>
<package xmlns="http://www.idpf.org/2007/opf" unique-identifier="book-id" version="3.0">
  <metadata xmlns:dc="http://purl.org/dc/elements/1.1/">
    <dc:identifier id="book-id">{book_id}</dc:identifier>
    <dc:title>{title}</dc:title>
    <dc:language>en</dc:language>
    <dc:creator id="author">{author}</dc:creator>
    <dc:publisher>Nous Publishing</dc:publisher>
    <dc:date>{datetime.now().strftime('%Y-%m-%d')}</dc:date>
    <meta property="dcterms:modified">{datetime.now().strftime('%Y-%m-%dT%H:%M:%SZ')}</meta>
  </metadata>
  <manifest>
{chr(10).join(manifest_items)}
  </manifest>
  <spine toc="ncx">
{chr(10).join(spine_refs)}
  </spine>
  <guide>
    <reference type="cover" title="Title Page" href="title.xhtml"/>
    <reference type="toc" title="Contents" href="toc.xhtml"/>
  </guide>
</package>'''

    # Build EPUB as zip
    mimetype_content = 'application/epub+zip'

    with zipfile.ZipFile(output_path, 'w', zipfile.ZIP_DEFLATED) as zf:
        # mimetype must be first, uncompressed, no extra fields
        zf.writestr('mimetype', mimetype_content, 
                     compress_type=zipfile.ZIP_STORED)

        # CSS
        zf.writestr('OEBPS/style/epub.css', EPUB_CSS)

        # XHTML files
        for fn, content in xhtml_files.items():
            zf.writestr(f'OEBPS/{fn}', content.encode('utf-8'))

        # OPF
        zf.writestr('OEBPS/content.opf', opf_content.encode('utf-8'))

        # NCX
        zf.writestr('OEBPS/toc.ncx', ncx_content.encode('utf-8'))

        # Container XML
        container_xml = '''<?xml version="1.0" encoding="utf-8"?>
<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container">
  <rootfiles>
    <rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/>
  </rootfiles>
</container>'''
        zf.writestr('META-INF/container.xml', container_xml.encode('utf-8'))

    return output_path


def process_book(book_key):
    """Process a single book through the full pipeline."""
    info = BOOKS[book_key]
    print(f"\n{'='*70}")
    print(f"  BOOK {info['number']}: {info['title']}")
    print(f"{'='*70}\n")

    book_dir = Path(info['dir'])
    md_path = book_dir / 'manuscript.md'
    html_path = book_dir / f'Book_{info["number"]}_{info["short_title"]}.html'
    pdf_path = book_dir / f'Book_{info["number"]}_{info["short_title"]}_Print.pdf'
    epub_path = book_dir / f'Book_{info["number"]}_{info["short_title"]}.epub'

    # Phase 1: Analyze
    print("Phase 1: Analyzing manuscript...")
    parsed = parse_manuscript(str(md_path))
    chapters = parsed['chapters']
    num_chapters = len(chapters)
    print(f"  Title: {parsed['title']}")
    print(f"  Chapters found: {num_chapters}")
    for ch in chapters:
        print(f"    Chapter {ch['number']}: {ch['title']}")

    # Phase 2: First pass - build HTML without page numbers
    print("\nPhase 2: First pass (render without page numbers)...")
    html_no_toc = build_print_html(info, chapters, page_map=None)

    with open(html_path, 'w', encoding='utf-8') as f:
        f.write(html_no_toc)
    print(f"  Written HTML: {html_path}")

    # Phase 3: First PDF render
    print("\nPhase 3: First PDF render...")
    render_pdf(html_no_toc, str(pdf_path))
    pdf_size = os.path.getsize(str(pdf_path))
    print(f"  First PDF: {pdf_path} ({pdf_size/1024:.0f} KB)")

    # Phase 4: Extract page numbers
    print("\nPhase 4: Extracting page numbers...")
    page_map, total_pages = extract_page_numbers(str(pdf_path), num_chapters)
    print(f"  Page map: {page_map}")

    # Phase 5: Rebuild HTML with hardcoded page numbers
    print("\nPhase 5: Final HTML with hardcoded page numbers...")
    html_final = build_print_html(info, chapters, page_map=page_map)

    with open(html_path, 'w', encoding='utf-8') as f:
        f.write(html_final)
    print(f"  Updated HTML: {html_path}")

    # Phase 6: Final PDF render
    print("\nPhase 6: Final PDF render...")
    render_pdf(html_final, str(pdf_path))
    pdf_size = os.path.getsize(str(pdf_path))
    print(f"  Final PDF: {pdf_path} ({pdf_size/1024:.0f} KB)")

    # Phase 7: Verify TOC
    print("\nPhase 7: Verifying TOC page numbers...")
    verify_page_map, total_pages_verify = extract_page_numbers(str(pdf_path), num_chapters)

    print("\n  TOC Verification:")
    print(f"  {'Ch#':>5} {'Page (TOC)':>12} {'Page (Actual)':>14} {'Match?':>8}")
    print(f"  {'-'*5} {'-'*12} {'-'*14} {'-'*8}")

    all_match = True
    for ch in chapters:
        n = ch['number']
        toc_page = page_map.get(n, '?')
        actual_page = verify_page_map.get(n, '?')
        match = "✓" if str(toc_page) == str(actual_page) else "✗"
        if match == "✗":
            all_match = False
        print(f"  {n:>5} {str(toc_page):>12} {str(actual_page):>14} {match:>8}")

    if all_match:
        print("\n  ✓ ALL PAGE NUMBERS MATCH!")
    else:
        print(f"\n  Adjusting with verified page numbers (page count: {total_pages} vs {total_pages_verify})...")
        html_corrected = build_print_html(info, chapters, page_map=verify_page_map)
        with open(html_path, 'w', encoding='utf-8') as f:
            f.write(html_corrected)
        render_pdf(html_corrected, str(pdf_path))
        print(f"  Re-rendered PDF with corrected page numbers")
        total_pages = total_pages_verify

    # Phase 8: Generate EPUB
    print("\nPhase 8: Generating EPUB 3...")
    generate_epub_manual(info, chapters, str(epub_path))
    epub_size = os.path.getsize(str(epub_path))
    print(f"  EPUB: {epub_path} ({epub_size/1024:.0f} KB)")

    # Summary
    print(f"\n{'─'*50}")
    print(f"  BOOK {info['number']}: {info['title']} — COMPLETE")
    print(f"  Chapters: {num_chapters}")
    print(f"  Pages: {total_pages}")
    print(f"  PDF size: {pdf_size/1024:.0f} KB")
    print(f"  EPUB size: {epub_size/1024:.0f} KB")
    print(f"{'─'*50}")

    return {
        'book': book_key,
        'title': info['title'],
        'chapters': num_chapters,
        'pages': total_pages,
        'pdf_size_kb': pdf_size/1024,
        'epub_size_kb': epub_size/1024,
        'page_map': page_map,
    }


def main():
    books_to_process = ['moon_rock', 'mooncoming', 'waters_end']
    results = []

    for book_key in books_to_process:
        try:
            result = process_book(book_key)
            results.append(result)
        except Exception as e:
            print(f"\nERROR processing {book_key}: {e}")
            import traceback
            traceback.print_exc()

    # Final summary
    print(f"\n{'='*70}")
    print("  FINAL SUMMARY")
    print(f"{'='*70}\n")
    print(f"  {'Book':<20} {'Chapters':<10} {'Pages':<10} {'PDF Size':<15} {'EPUB Size':<15}")
    print(f"  {'─'*20} {'─'*10} {'─'*10} {'─'*15} {'─'*15}")
    for r in results:
        print(f"  {r['title']:<20} {r['chapters']:<10} {r['pages']:<10} {r['pdf_size_kb']:<15.0f} {r['epub_size_kb']:<15.0f}")

    print(f"\n  All outputs in respective book directories:")
    for r in results:
        info = BOOKS[r['book']]
